```go
// printLocalReadme displays the README of the repository in the current
// directory when it cannot be resolved to a GitHub remote. It is used by
// `gh repo view .` as a fallback when no remote is configured.
func printLocalReadme(opts *ViewOptions) error {
	var readmeFilename string
	for _, filename := range []string{"README.md", "README.markdown", "README.mdown", "README.mkdown", "README"} {
		if fi, err := os.Stat(filename); err == nil && !fi.IsDir() {
			readmeFilename = filename
			break
		}
	}
	if readmeFilename == "" {
		return fmt.Errorf("could not find a README in the current directory and no git remote is configured")
	}

	content, err := os.ReadFile(readmeFilename)
	if err != nil {
		return err
	}

	err = opts.IO.StartPager()
	if err != nil {
		return err
	}
	defer opts.IO.StopPager()

	stdout := opts.IO.Out
	fmt.Fprintf(stdout, "name:\t%s\n", ".")
	fmt.Fprintf(stdout, "description:\t%s\n", utils.Gray("README from local file"))
	fmt.Fprintln(stdout, "--")
	fmt.Fprintln(stdout, string(content))
	fmt.Fprintln(stdout)
	return nil
}
```

